    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'Patient #25840: A 3-year-old child presents with a limp that started yesterday morning. Two weeks ago, he had a mild URI. He is well-appearing. He refuses to bear weight fully but has only mild pain with passive hip ROM. Labs show a normal WBC count and an ESR of 15 mm/hr. What is the most likely diagnosis?', '["Juvenile idiopathic arthritis", "Septic arthritis", "Slipped capital femoral epiphysis", "Legg-Calv\u00e9-Perthes disease", "Transient synovitis"]'::jsonb, 4, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 12-year-old volleyball player complains of anterior knee pain that is worse after practice and jumping. Examination reveals point tenderness and a bony prominence over the tibial tubercle. Radiographs show fragmentation of the tibial tubercle apophysis. What is the most appropriate management?', '["Intra-articular corticosteroid injection", "Strict non-weight bearing with crutches", "Surgical excision of the ossicle", "Activity modification, ice, NSAIDs, and reassurance", "Immobilization in a long leg cast for 6 weeks"]'::jsonb, 3, 'Osgood-Schlatter disease is a traction apophysitis of the tibial tubercle, common in active adolescents experiencing rapid growth. It is a self-limiting condition. Treatment is symptomatic with rest, ice, NSAIDs, and physical therapy (quadriceps/hamstring stretching).'),
    (v_topic_id, 'A 21-day-old infant is brought to the clinic for bilateral clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Adductus", "Varus", "Cavus", "Supination", "Equinus"]'::jsonb, 4, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 5-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the left. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["Ultrasound of the hips", "CT scan of the pelvis", "Bone scan", "AP radiograph of the pelvis", "MRI of the hips"]'::jsonb, 0, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'A 14-year-old heavy-set male presents with left groin and knee pain. He walks with a limp. On examination, when his left hip is passively flexed, it obligatorily goes into external rotation. Radiographs show a posterior and inferior displacement of the proximal femoral epiphysis. What is the most appropriate management?', '["Closed reduction and spica casting", "Immediate non-weight bearing and in situ percutaneous pinning", "Open reduction and internal fixation", "Pavlik harness", "Physical therapy and weight loss"]'::jsonb, 1, 'Slipped Capital Femoral Epiphysis (SCFE) occurs typically in overweight adolescents. The hallmark physical exam finding is obligatory external rotation with hip flexion. Treatment is strictly in situ pinning (without attempts at forceful closed reduction, which increases the risk of avascular necrosis) to stabilize the physis.'),
    (v_topic_id, 'Patient #33834: A 3-year-old child presents with a limp that started yesterday morning. Two weeks ago, he had a mild URI. He is well-appearing. He refuses to bear weight fully but has only mild pain with passive hip ROM. Labs show a normal WBC count and an ESR of 15 mm/hr. What is the most likely diagnosis?', '["Juvenile idiopathic arthritis", "Septic arthritis", "Transient synovitis", "Slipped capital femoral epiphysis", "Legg-Calv\u00e9-Perthes disease"]'::jsonb, 2, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 5-day-old infant is brought to the clinic for bilateral clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Equinus", "Adductus", "Cavus", "Supination", "Varus"]'::jsonb, 0, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 12-day-old infant is brought to the clinic for unilateral right clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Varus", "Adductus", "Equinus", "Supination", "Cavus"]'::jsonb, 2, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 13-day-old infant is brought to the clinic for unilateral left clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Cavus", "Adductus", "Equinus", "Varus", "Supination"]'::jsonb, 2, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 3-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the right. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["Bone scan", "AP radiograph of the pelvis", "Ultrasound of the hips", "MRI of the hips", "CT scan of the pelvis"]'::jsonb, 2, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'A 15-year-old basketball player complains of anterior knee pain that is worse after practice and jumping. Examination reveals point tenderness and a bony prominence over the tibial tubercle. Radiographs show fragmentation of the tibial tubercle apophysis. What is the most appropriate management?', '["Strict non-weight bearing with crutches", "Immobilization in a long leg cast for 6 weeks", "Activity modification, ice, NSAIDs, and reassurance", "Surgical excision of the ossicle", "Intra-articular corticosteroid injection"]'::jsonb, 2, 'Osgood-Schlatter disease is a traction apophysitis of the tibial tubercle, common in active adolescents experiencing rapid growth. It is a self-limiting condition. Treatment is symptomatic with rest, ice, NSAIDs, and physical therapy (quadriceps/hamstring stretching).'),
    (v_topic_id, 'Patient #27468: A 4-year-old child presents with a limp that started yesterday morning. Two weeks ago, he had a mild URI. He is well-appearing. He refuses to bear weight fully but has only mild pain with passive hip ROM. Labs show a normal WBC count and an ESR of 15 mm/hr. What is the most likely diagnosis?', '["Septic arthritis", "Transient synovitis", "Slipped capital femoral epiphysis", "Juvenile idiopathic arthritis", "Legg-Calv\u00e9-Perthes disease"]'::jsonb, 1, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 8-year-old child refuses to bear weight on the right leg. The hip is held in flexion, abduction, and external rotation. Temperature is 39.5°C. Laboratory evaluation shows a WBC count of 15,000/mm³ and an ESR of 50 mm/hr. According to the Kocher criteria, what is the probability that this child has septic arthritis rather than transient synovitis?', '["< 10% (Very low probability)", "Exactly 0%", "> 90% (Very high probability)", "About 50%", "About 25%"]'::jsonb, 2, 'The Kocher criteria differentiate septic arthritis from transient synovitis. The 4 criteria are: non-weight-bearing, fever > 38.5°C, ESR > 40 mm/hr, and WBC > 12,000/mm³. Having all 4 predictors yields a 99% probability of septic arthritis; 3 predictors yield a 93% probability. This child has 4 predictors.'),
    (v_topic_id, 'A 11-year-old overweight male presents with left groin and knee pain. He walks with a limp. On examination, when his left hip is passively flexed, it obligatorily goes into external rotation. Radiographs show a posterior and inferior displacement of the proximal femoral epiphysis. What is the most appropriate management?', '["Immediate non-weight bearing and in situ percutaneous pinning", "Physical therapy and weight loss", "Pavlik harness", "Open reduction and internal fixation", "Closed reduction and spica casting"]'::jsonb, 0, 'Slipped Capital Femoral Epiphysis (SCFE) occurs typically in overweight adolescents. The hallmark physical exam finding is obligatory external rotation with hip flexion. Treatment is strictly in situ pinning (without attempts at forceful closed reduction, which increases the risk of avascular necrosis) to stabilize the physis.'),
    (v_topic_id, 'A 7-year-old boy presents with a painless limp that has worsened over several weeks. He occasionally complains of vague right knee and thigh pain. He is afebrile and has limited internal rotation and abduction of the right hip. Radiographs show increased density and a subchondral crescent sign in the femoral head. What is the most likely diagnosis?', '["Legg-Calv\u00e9-Perthes disease", "Developmental dysplasia of the hip", "Slipped capital femoral epiphysis", "Transient synovitis", "Septic arthritis"]'::jsonb, 0, 'Legg-Calvé-Perthes disease is idiopathic avascular necrosis of the femoral head, classically seen in boys aged 4-8. It often presents insidiously with a painless limp or referred pain to the thigh/knee. Radiographs progress from sclerosis to fragmentation and reossification. The crescent sign represents a subchondral fracture.'),
    (v_topic_id, 'A 11-year-old basketball player complains of anterior knee pain that is worse after practice and jumping. Examination reveals point tenderness and a bony prominence over the tibial tubercle. Radiographs show fragmentation of the tibial tubercle apophysis. What is the most appropriate management?', '["Strict non-weight bearing with crutches", "Surgical excision of the ossicle", "Intra-articular corticosteroid injection", "Immobilization in a long leg cast for 6 weeks", "Activity modification, ice, NSAIDs, and reassurance"]'::jsonb, 4, 'Osgood-Schlatter disease is a traction apophysitis of the tibial tubercle, common in active adolescents experiencing rapid growth. It is a self-limiting condition. Treatment is symptomatic with rest, ice, NSAIDs, and physical therapy (quadriceps/hamstring stretching).'),
    (v_topic_id, 'Patient #15993: A 4-year-old child presents with a limp that started yesterday morning. Two weeks ago, he had a mild URI. He is well-appearing. He refuses to bear weight fully but has only mild pain with passive hip ROM. Labs show a normal WBC count and an ESR of 15 mm/hr. What is the most likely diagnosis?', '["Juvenile idiopathic arthritis", "Septic arthritis", "Transient synovitis", "Slipped capital femoral epiphysis", "Legg-Calv\u00e9-Perthes disease"]'::jsonb, 2, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 14-day-old infant is brought to the clinic for bilateral clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Equinus", "Cavus", "Supination", "Varus", "Adductus"]'::jsonb, 0, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 10-year-old volleyball player complains of anterior knee pain that is worse after practice and jumping. Examination reveals point tenderness and a bony prominence over the tibial tubercle. Radiographs show fragmentation of the tibial tubercle apophysis. What is the most appropriate management?', '["Activity modification, ice, NSAIDs, and reassurance", "Intra-articular corticosteroid injection", "Strict non-weight bearing with crutches", "Surgical excision of the ossicle", "Immobilization in a long leg cast for 6 weeks"]'::jsonb, 0, 'Osgood-Schlatter disease is a traction apophysitis of the tibial tubercle, common in active adolescents experiencing rapid growth. It is a self-limiting condition. Treatment is symptomatic with rest, ice, NSAIDs, and physical therapy (quadriceps/hamstring stretching).'),
    (v_topic_id, 'Patient #60081: A 15-year-old boy presents with frequent ankle sprains and a painful, rigid flatfoot. Examination reveals severe restriction of subtalar motion and spasm of the peroneal muscles. Radiographs show a ''C-sign'' on the lateral view. What is the most likely diagnosis?', '["Sever disease", "Flexible pes planus", "Calcaneonavicular coalition", "Talocalcaneal coalition", "Posterior tibial tendon insufficiency"]'::jsonb, 3, 'Detailed orthopedic assessment of the pediatric patient is required to identify these specific conditions correctly and avoid serious long-term complications.'),
    (v_topic_id, 'A 8-year-old falls from a trampoline and sustains a significantly displaced extension-type supracondylar humerus fracture. Upon examination, the child is unable to make an ''OK'' sign (unable to flex the IP joint of the thumb and DIP joint of the index finger). Which nerve is most likely injured?', '["Axillary nerve", "Anterior interosseous nerve (AIN)", "Ulnar nerve", "Musculocutaneous nerve", "Radial nerve"]'::jsonb, 1, 'The anterior interosseous nerve (AIN), a branch of the median nerve, is the most commonly injured nerve in extension-type supracondylar humerus fractures. Injury manifests as an inability to flex the IP joint of the thumb (flexor pollicis longus) and the DIP of the index finger (flexor digitorum profundus), resulting in an inability to make the ''''A-OK'''' sign.'),
    (v_topic_id, 'A 12-week-old infant, born breech, presents for a routine well-child check. Examination reveals asymmetric thigh skin folds and a positive Ortolani maneuver on the right. What is the most appropriate initial imaging modality to confirm the diagnosis?', '["CT scan of the pelvis", "AP radiograph of the pelvis", "Ultrasound of the hips", "Bone scan", "MRI of the hips"]'::jsonb, 2, 'Developmental Dysplasia of the Hip (DDH) is most accurately assessed with ultrasound in infants under 4-6 months of age because the femoral head and acetabulum are predominantly cartilaginous and not fully visible on radiographs. A positive Ortolani test (reduction of a dislocated hip) strongly suggests DDH.'),
    (v_topic_id, 'A 8-year-old gymnastics player presents with posterior heel pain. The pain worsens after running and improves with rest. Examination reveals tenderness upon medial-lateral compression of the calcaneal tuberosity (positive ''squeeze test''). There is tightness of the Achilles tendon. What is the most likely diagnosis?', '["Achilles tendon rupture", "Plantar fasciitis", "Calcaneal apophysitis (Sever disease)", "Calcaneal stress fracture", "Tarsal coalition"]'::jsonb, 2, 'Sever disease is a traction apophysitis of the calcaneus where the Achilles tendon inserts. It is a common cause of heel pain in athletic children aged 8-12. The classic exam finding is pain with medial/lateral compression of the heel. Treatment includes heel cups, calf stretching, and NSAIDs.'),
    (v_topic_id, 'A 18-day-old infant is brought to the clinic for unilateral left clubfoot (talipes equinovarus). The parents ask about the treatment plan. According to the Ponseti method, the deformities are corrected with serial casting in a specific sequence. Which component of the deformity is corrected LAST?', '["Supination", "Varus", "Equinus", "Cavus", "Adductus"]'::jsonb, 2, 'In the Ponseti method for clubfoot, the CAVE deformities are corrected sequentially: Cavus (elevating the first ray), Adductus, Varus, and finally Equinus. The equinus correction often requires a percutaneous Achilles tenotomy.'),
    (v_topic_id, 'A 11-year-old basketball player presents with posterior heel pain. The pain worsens after running and improves with rest. Examination reveals tenderness upon medial-lateral compression of the calcaneal tuberosity (positive ''squeeze test''). There is tightness of the Achilles tendon. What is the most likely diagnosis?', '["Plantar fasciitis", "Achilles tendon rupture", "Calcaneal stress fracture", "Tarsal coalition", "Calcaneal apophysitis (Sever disease)"]'::jsonb, 4, 'Sever disease is a traction apophysitis of the calcaneus where the Achilles tendon inserts. It is a common cause of heel pain in athletic children aged 8-12. The classic exam finding is pain with medial/lateral compression of the heel. Treatment includes heel cups, calf stretching, and NSAIDs.'),
